  --bg: #0b1220;
  --panel: #0f1a2e;
  --panel-2: #0c1628;
  --text: #e8eefc;
  --muted: rgba(232, 238, 252, 0.72);
  --grid: rgba(232, 238, 252, 0.10);
  --accent: #7aa2ff;
  --shadow: 0 12px 30px rgba(0, 0, 0, 0.40);
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  background: radial-gradient(1200px 800px at 20% 10%, #16264a 0%, var(--bg) 55%, #070b13 100%);
  color: var(--text);
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
}

.site-header {
  padding: 18px 22px;
  border-bottom: 1px solid var(--grid);
  background: linear-gradient(180deg, rgba(15, 26, 46, 0.85), rgba(15, 26, 46, 0.45));
  backdrop-filter: blur(6px);
}

.site-header__inner {
  max-width: 1400px;
  margin: 0 auto;
}

h1 {
  margin: 0;
  font-size: 20px;
  letter-spacing: 0.3px;
}

.subtitle {
  margin: 6px 0 0 0;
  color: var(--muted);
  font-size: 13px;
}

.app {
  max-width: 1400px;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  gap: 14px;
}

.panel {
  background: linear-gradient(180deg, rgba(15, 26, 46, 0.86), rgba(12, 22, 40, 0.86));
  border: 1px solid var(--grid);
  border-radius: 14px;
  box-shadow: var(--shadow);
  overflow: hidden;
  min-height: 720px;
}

.panel__header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--grid);
  background: rgba(10, 18, 33, 0.55);
}

.panel__header h2 {
  margin: 0;
  font-size: 15px;
  letter-spacing: 0.2px;
}

.panel__footer {
  padding: 10px 14px;
  border-top: 1px solid var(--grid);
  color: var(--muted);
  font-size: 12px;
  background: rgba(10, 18, 33, 0.35);
}

.panel--chart {
  flex: 0 0 58%;
}

.panel--table {
  flex: 1 1 auto;
  background: linear-gradient(180deg, rgba(15, 26, 46, 0.92), rgba(10, 18, 33, 0.92));
}

.legend {
  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.chart {
  position: relative;
  padding: 10px;
}

#bubble-svg {
  width: 100%;
  height: 640px;
  display: block;
  border-radius: 12px;
  background: radial-gradient(900px 560px at 40% 35%, rgba(122, 162, 255, 0.12), rgba(0, 0, 0, 0) 60%);
}

.bubble {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1px;
}

.bubble.selected {
  stroke: #ffffff;
  stroke-width: 3px;
}

.bubble-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  fill: rgba(255, 255, 255, 0.92);
  pointer-events: none;
  user-select: none;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 120ms ease, transform 120ms ease;
  padding: 10px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(8, 12, 22, 0.92);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.55);
  font-size: 12px;
  color: var(--text);
  max-width: 320px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .tt-title {
  font-weight: 800;
  margin-bottom: 4px;
}

.tooltip .tt-sub {
  color: var(--muted);
}

.table-wrap {
  height: calc(720px - 49px);
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: rgba(10, 18, 33, 0.92);
  border-bottom: 1px solid var(--grid);
  text-align: left;
  padding: 10px 10px;
  color: rgba(232, 238, 252, 0.92);
}

tbody td {
  border-bottom: 1px solid rgba(232, 238, 252, 0.08);
  padding: 9px 10px;
  color: rgba(232, 238, 252, 0.88);
}

tbody tr {
  cursor: pointer;
}

tbody tr:hover {
  background: rgba(122, 162, 255, 0.10);
}

tbody tr.selected {
  background: rgba(122, 162, 255, 0.22);
  outline: 1px solid rgba(255, 255, 255, 0.22);
}

td.num, th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.hint {
  color: var(--muted);
}

@media (max-width: 1100px) {
  .app {
    flex-direction: column;
  }

  .panel--chart {
    flex: 1 1 auto;
  }

  .panel {
    min-height: 0;
  }

  .table-wrap {
    height: 520px;
  }
}
"}

{"security_risk": "MEDIUM", "summary": "Create D3 v6 visualization logic for bubble chart and table", "command": "create", "path": "/root/output/js/visualization.js", "file_text": "/* global d3 */

(function () {
  const DATA_PATH = 'data/stock-descriptions.csv';

  const bubbleSvg = d3.select('#bubble-svg');
  const legendEl = d3.select('#legend');
  const tooltip = d3.select('#tooltip');

  const DEFAULT_WIDTH = 780;
  const DEFAULT_HEIGHT = 640;

  let selectedTicker = null;

  function normalizeRow(d) {
    const ticker = (d.ticker || '').trim();
    const name = (d['full name'] || '').trim();
    const sector = (d.sector || '').trim();

    const marketCapRaw = (d.marketCap == null ? '' : String(d.marketCap)).trim();
    const marketCap = marketCapRaw === '' ? null : +marketCapRaw;

    const country = (d.country || '').trim();
    const website = (d.website || '').trim();

    const isETF = !(Number.isFinite(marketCap) && marketCap > 0);

    return {
      ticker,
      name,
      sector,
      marketCap: isETF ? null : marketCap,
      isETF,
      country,
      website,
      hasTooltipData: Boolean(ticker) && Boolean(name) && Boolean(sector) && !isETF && country !== '' && website !== ''
    };
  }

  function formatMarketCap(n) {
    if (!Number.isFinite(n) || n <= 0) return '—';

    const abs = Math.abs(n);
    const fmt = (value, suffix) => {
      const a = Math.abs(value);
      let digits = 2;
      if (a >= 100) digits = 0;
      else if (a >= 10) digits = 1;
      let s = value.toFixed(digits);
      s = s.replace(/\.0+$|(?<=\.[0-9]*[1-9])0+$/g, '');
      return `${s}${suffix}`;
    };

    if (abs >= 1e12) return fmt(n / 1e12, 'T');
    if (abs >= 1e9) return fmt(n / 1e9, 'B');
    if (abs >= 1e6) return fmt(n / 1e6, 'M');
    if (abs >= 1e3) return fmt(n / 1e3, 'K');
    return String(Math.round(n));
  }

  function setSelectedKey(ticker) {
    const next = selectedTicker === ticker ? null : ticker;
    selectedTicker = next;
    renderSelection();
  }

  function renderSelection() {
    d3.selectAll('circle.bubble')
      .classed('selected', d => d.ticker === selectedTicker);

    const rows = d3.selectAll('#data-table tbody tr');
    rows.classed('selected', d => d.ticker === selectedTicker);

    if (selectedTicker) {
      const row = rows.filter(d => d.ticker === selectedTicker).node();
      if (row) row.scrollIntoView({ block: 'nearest' });
    }
  }

  function buildLegend(sectors, color) {
    legendEl.selectAll('*').remove();

    const items = legendEl
      .selectAll('div.legend-item')
      .data(sectors, d => d)
      .join('div')
      .attr('class', 'legend-item');

    items.append('span')
      .attr('class', 'legend-swatch')
      .style('background', d => color(d));

    items.append('span')
      .text(d => d);
  }

  function buildTable(data) {
    const tbody = d3.select('#data-table tbody');

    const rows = tbody
      .selectAll('tr')
      .data(data, d => d.ticker)
      .join('tr')
      .on('click', (event, d) => setSelectedKey(d.ticker));

    rows.selectAll('td')
      .data(d => ([
        { key: 'ticker', value: d.ticker, className: '' },
        { key: 'name', value: d.name, className: '' },
        { key: 'sector', value: d.sector, className: '' },
        { key: 'marketCap', value: formatMarketCap(d.marketCap), className: 'num' }
      ]), d => d.key)
      .join('td')
      .attr('class', d => d.className)
      .text(d => d.value);

    return rows;
  }

  function makePalette(n) {
    const palettes = [
      d3.schemeTableau10,
      d3.schemeSet3,
      d3.schemePaired,
      d3.schemeSet2,
      d3.schemeCategory10
    ];

    const colors = [];
    for (const p of palettes) {
      for (const c of p) colors.push(c);
    }

    if (colors.length >= n) return colors.slice(0, n);

    while (colors.length < n) {
      colors.push(colors[colors.length % palettes[0].length]);
    }
    return colors;
  }

  function showTooltip(event, d) {
    tooltip
      .classed('visible', true)
      .attr('aria-hidden', 'false')
      .html(
        `<div class="tt-title">${d.ticker}</div>` +
        `<div class="tt-sub">${d.name}</div>` +
        `<div class="tt-sub">Sector: ${d.sector}</div>`
      );
    moveTooltip(event);
  }

  function moveTooltip(event) {
    const pad = 12;
    const { clientX, clientY } = event;

    tooltip
      .style('left', `${clientX + pad}px`)
      .style('top', `${clientY + pad}px`);
  }

  function hideTooltip() {
    tooltip
      .classed('visible', false)
      .attr('aria-hidden', 'true');
  }

  function renderBubbleChart(data) {
    const width = DEFAULT_WIDTH;
    const height = DEFAULT_HEIGHT;

    bubbleSvg
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('preserveAspectRatio', 'xMidYMid meet');

    bubbleSvg.selectAll('*').remove();

    const sectors = Array.from(new Set(data.map(d => d.sector))).sort(d3.ascending);

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(makePalette(sectors.length));

    buildLegend(sectors, color);

    const caps = data.map(d => d.marketCap).filter(d => Number.isFinite(d));
    const capMin = d3.min(caps);
    const capMax = d3.max(caps);

    const rScale = d3.scaleSqrt()
      .domain([capMin || 1, capMax || 1])
      .range([12, 48]);

    const etfRadius = 14;

    // Deterministic node order for stable layout.
    const nodes = data
      .slice()
      .sort((a, b) => d3.ascending(a.ticker, b.ticker))
      .map((d, i) => {
        const r = d.isETF ? etfRadius : rScale(d.marketCap);
        return {
          ...d,
          r,
          x: (width / 2) + ((i % 10) - 5) * 8,
          y: (height / 2) + ((Math.floor(i / 10) % 5) - 2) * 10,
          vx: 0,
          vy: 0
        };
      });

    const cx = width / 2;
    const cy = height / 2;
    const ring = Math.min(width, height) * 0.22;

    const sectorCenters = new Map();
    sectors.forEach((s, i) => {
      const angle = (2 * Math.PI * i) / sectors.length;
      sectorCenters.set(s, {
        x: cx + ring * Math.cos(angle),
        y: cy + ring * Math.sin(angle)
      });
    });

    const simulation = d3.forceSimulation(nodes)
      .force('center', d3.forceCenter(cx, cy))
      .force('charge', d3.forceManyBody().strength(-4))
      .force('x', d3.forceX(d => sectorCenters.get(d.sector).x).strength(0.13))
      .force('y', d3.forceY(d => sectorCenters.get(d.sector).y).strength(0.13))
      .force('collide', d3.forceCollide(d => d.r + 1).iterations(2))
      .stop();

    // Fixed tick count => deterministic layout.
    for (let i = 0; i < 350; i += 1) simulation.tick();

    const root = bubbleSvg.append('g');

    const node = root
      .selectAll('g.node')
      .data(nodes, d => d.ticker)
      .join(enter => {
        const g = enter.append('g').attr('class', 'node');

        g.append('circle')
          .attr('class', 'bubble')
          .attr('r', d => d.r)
          .attr('fill', d => color(d.sector))
          .attr('fill-opacity', d => (d.isETF ? 0.55 : 0.80));

        g.append('text')
          .attr('class', 'bubble-label')
          .attr('text-anchor', 'middle')
          .attr('dy', '0.35em')
          .text(d => d.ticker);

        return g;
      });

    node
      .attr('transform', d => `translate(${d.x},${d.y})`)
      .on('mouseover', (event, d) => {
        if (!d.hasTooltipData) return;
        showTooltip(event, d);
      })
      .on('mousemove', (event, d) => {
        if (!d.hasTooltipData) return;
        moveTooltip(event);
      })
      .on('mouseout', () => hideTooltip())
      .on('click', (event, d) => setSelectedKey(d.ticker));

    renderSelection();
  }

  async function main() {
    let raw;
    try {
      raw = await d3.csv(DATA_PATH, normalizeRow);
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error(err);
      d3.select('#app')
        .insert('div', ':first-child')
        .style('padding', '14px')
        .style('color', 'rgba(232,238,252,0.9)')
        .text('Failed to load data. Make sure the /output/data folder is present.');
      return;
    }

    const data = raw
      .filter(d => d.ticker !== '')
      .sort((a, b) => d3.ascending(a.ticker, b.ticker));

    buildTable(data);
    renderBubbleChart(data);
  }

  main();
})();
"}

