  font-size: 12px;
  background: rgba(10, 18, 33, 0.35);
}

.panel--chart {
  flex: 0 0 58%;
}

.panel--table {
  flex: 1 1 auto;
  background: linear-gradient(180deg, rgba(15, 26, 46, 0.92), rgba(10, 18, 33, 0.92));
}

.legend {
  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.chart {
  position: relative;
  padding: 10px;
}

#bubble-svg {
  width: 100%;
  height: 640px;
  display: block;
  border-radius: 12px;
  background: radial-gradient(900px 560px at 40% 35%, rgba(122, 162, 255, 0.12), rgba(0, 0, 0, 0) 60%);
}

.bubble {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1px;
}

.bubble.selected {
  stroke: #ffffff;
  stroke-width: 3px;
}

.bubble-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  fill: rgba(255, 255, 255, 0.92);
