  margin-top: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  white-space: nowrap;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  border: 1px solid rgba(255, 255, 255, 0.18);
}

.chart {
  position: relative;
  padding: 10px;
}

#bubble-svg {
  width: 100%;
  height: 640px;
  display: block;
  border-radius: 12px;
  background: radial-gradient(900px 560px at 40% 35%, rgba(122, 162, 255, 0.12), rgba(0, 0, 0, 0) 60%);
}

.bubble {
  stroke: rgba(255, 255, 255, 0.25);
  stroke-width: 1px;
}

.bubble.selected {
  stroke: #ffffff;
  stroke-width: 3px;
}

.bubble-label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
  fill: rgba(255, 255, 255, 0.92);
  pointer-events: none;
  user-select: none;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 120ms ease, transform 120ms ease;
  padding: 10px 11px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(8, 12, 22, 0.92);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.55);
  font-size: 12px;
  color: var(--text);
  max-width: 320px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .tt-title {
  font-weight: 800;
  margin-bottom: 4px;
}

.tooltip .tt-sub {
  color: var(--muted);
}

.table-wrap {
  height: calc(720px - 49px);
  overflow: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: rgba(10, 18, 33, 0.92);
  border-bottom: 1px solid var(--grid);
  text-align: left;
  padding: 10px 10px;
  color: rgba(232, 238, 252, 0.92);
}

tbody td {
  border-bottom: 1px solid rgba(232, 238, 252, 0.08);
  padding: 9px 10px;
  color: rgba(232, 238, 252, 0.88);
}

tbody tr {
  cursor: pointer;
}

tbody tr:hover {
  background: rgba(122, 162, 255, 0.10);
}

tbody tr.selected {
  background: rgba(122, 162, 255, 0.22);
  outline: 1px solid rgba(255, 255, 255, 0.22);
}

td.num, th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.hint {
  color: var(--muted);
}

@media (max-width: 1100px) {
  .app {
    flex-direction: column;
  }

  .panel--chart {
    flex: 1 1 auto;
  }

  .panel {
    min-height: 0;
  }

  .table-wrap {
    height: 520px;
  }
}
