}

td.num, th.num {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.hint {
  color: var(--muted);
}

@media (max-width: 1100px) {
  .app {
    flex-direction: column;
  }

  .panel--chart {
    flex: 1 1 auto;
  }

  .panel {
    min-height: 0;
  }

  .table-wrap {
    height: 520px;
  }
}
